public class Main {
    static int minute(String hhmm) {
        if (!hhmm.matches("\\d{2}:\\d{2}")) return -1;
        int h = Integer.parseInt(hhmm.substring(0, 2)), m = Integer.parseInt(hhmm.substring(3));
        return h < 24 && m < 60 ? h * 60 + m : -1;
    }

