            String[] p = raw.trim().split("\\s+");
            if (p[0].isEmpty()) continue;
            String reply;
            if (p[0].equals("SLOTS") && p.length == 3 && p[1].matches("\\d+") && p[2].matches("\\d+")) {
                lot = new ParkingLot(Integer.parseInt(p[1]), Integer.parseInt(p[2]));
                reply = "lot ready: " + p[1] + " bike, " + p[2] + " car slots";
            } else if (lot == null) reply = "error: no lot yet";
            else if (p[0].equals("PARK") && p.length == 4 && (p[2].equals("BIKE") || p[2].equals("CAR")) && minute(p[3]) >= 0)
