import java.util.*;

class ParkingLot {
    static final int FREE_MINUTES = 15;
    private final Map<String, Integer> free = new HashMap<>();
    private final Map<String, Ticket> parked = new HashMap<>();
    private int nextTicket = 1;

    ParkingLot(int bikes, int cars) {
        free.put("BIKE", bikes);
        free.put("CAR", cars);
    }

    int freeSlots(String type) { return free.get(type); }

    String park(String plate, String type, int minute) {
        if (parked.containsKey(plate)) return "error: " + plate + " is already parked";
        if (free.get(type) == 0) return "error: no " + type.toLowerCase() + " slot free";
        free.merge(type, -1, Integer::sum);
        Ticket t = new Ticket(nextTicket++, plate, type, minute);
        parked.put(plate, t);
        return "ticket " + t.number + " for " + plate;
    }

    String leave(String plate, int minute) {
        Ticket t = parked.get(plate);
        if (t == null) return "error: " + plate + " is not parked";
        if (minute < t.inMinute) return "error: time goes backwards";
        parked.remove(plate);
        free.merge(t.type, 1, Integer::sum);
        return plate + " paid " + fee(t.type, minute - t.inMinute);
    }

    static int fee(String type, int minutes) {
        if (minutes <= FREE_MINUTES) return 0;
        int hours = (minutes + 59) / 60;
        return hours * (type.equals("BIKE") ? 10 : 20);
    }
}
